#include <bits/stdc++.h>

#define push_backx x
using namespace std;
using LL = long long;
const int MOD = 1e9+7;

int qpow(int base, int exp, int mod, int res=1) {
    for(; exp; exp>>=1, base=(LL)base*base%mod) if(exp & 1) res = (LL)res * base % mod;
    return res;
}

const int MAXN = 1<<7;
int pMat[MAXN][MAXN];
int proMat[MAXN][MAXN];
int popcnt[MAXN];
INT qArray[MAXN][MAXN];
int n;
int idxMap[MAXN];
vector<int> groupsByCount[MAXN];
map<pair<int, LL>, int> memoMap;

inline void add_mod(int &a, int b) {a+=b; if(a>=MOD) a -= MOD;}

int recurse(int index, LL state) {
    if(state == 0) return 0;
    if(index == n) return 1;
    if(memoMap.count({index, state})) return memoMap[{index, state}];
    int total=0;
    for(int subset=1; subset<(1<<n); ++subset) {
        LL new_state=0;
        for(int k=0; k<(int)groupsByCount[index].size(); ++k) {
            if(!(state & (1LL<<k))) continue;
            int c=groupsByCount[index][k];
            int nxt=subset - (subset & c);
            new_state |= qArray[c][nxt];
        }
        add_mod(total, (LL)proMat[index][subset] * recurse(index+1, new_state) % MOD);
    }
    return memoMap[{index, state}] = total;
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("in.in", "r", stdin);
    freopen("out.out", "w", stdout);
#endif
    scanf("%d", &n);
    int inv_100 = power(100, MOD-2, MOD);
    for(int i=0; i<n; i++) {
        for(int j=0; j<n; j++) {
            scanf("%d", pMat[i]+j);
            pMat[i][j] = (LL)pMat[i][j] * inv_100 % MOD;
        }
    }
    for(int i=0; i<n; i++) {
        for(int j=0; j<(1<<n); j++) {
            proMat[i][j] = 1;
            for(int k=0; k<n; k++) {
                if((j>>k)&1) {
                    proMat[i][j] = (LL)proMat[i][j] * pMat[i][k] % MOD;
                } else {
                    proMat[i][j] = (LL)proMat[i][j] * (MOD+1 - pMat[i][k]) % MOD;
                }
            }
        }
    }
    for(int i=0; i<(1<<n); i++) popcnt[i]=__builtin_popcount(i);
    for(int i=0; i<(1<<n); i++) {
        groupsByCount[popcnt[i]].push_back(i);
        idxMap[i] = (int)groupsByCount[popcnt[i]].size() - 1;
    }
    for(int i=0; i<(1<<n); i++) {
        for(int j=0; j<n; j++) {
            if(!((i>>j)&1)) qArray[i][1<<j]=1LL<<idxMap[i|(1<<j)];
        }
        for(int j=0; j<(1<<n); j++) {
            qArray[i][j]=qArray[i][j&-j]|qArray[i][j^(j&-j)];
        }
    }
    cout << recurse(0, 1) << endl;
}
